using System;
using Munshiganj.Core;
using NUnit.Framework;

namespace Munshiganj.Tests
{
    /// <summary>
    /// Tests for the "new PlaneMesh" ground generated by <see cref="PlaneMeshBuilder"/>.
    /// The same file is executed by the Unity Test Runner (EditMode) and by the portable
    /// runner in Tests/Portable.
    /// </summary>
    public class PlaneMeshBuilderTests
    {
        const float Tolerance = 0.0001f;

        [Test]
        public void Build_CreatesTheExpectedVertexCount()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 20f, 4, 5);

            Assert.AreEqual((4 + 1) * (5 + 1), data.VertexCount);
        }

        [Test]
        public void Build_CreatesTwoTrianglesPerQuad()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 20f, 4, 5);

            Assert.AreEqual(4 * 5 * 2, data.TriangleCount);
            Assert.AreEqual(data.TriangleCount * 3, data.Indices.Length);
        }

        [Test]
        public void Build_PlacesThePlaneOnTheXZAxis()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 20f, 1, 1);

            for (int i = 0; i < data.Positions.Length; i += 3)
            {
                Assert.AreEqual(0f, data.Positions[i + 1], Tolerance);
            }
        }

        [Test]
        public void Build_CentersThePlaneOnTheOrigin()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 20f, 2, 2);

            float minX = float.MaxValue;
            float maxX = float.MinValue;
            float minZ = float.MaxValue;
            float maxZ = float.MinValue;

            for (int i = 0; i < data.Positions.Length; i += 3)
            {
                minX = Math.Min(minX, data.Positions[i]);
                maxX = Math.Max(maxX, data.Positions[i]);
                minZ = Math.Min(minZ, data.Positions[i + 2]);
                maxZ = Math.Max(maxZ, data.Positions[i + 2]);
            }

            Assert.AreEqual(-5f, minX, Tolerance);
            Assert.AreEqual(5f, maxX, Tolerance);
            Assert.AreEqual(-10f, minZ, Tolerance);
            Assert.AreEqual(10f, maxZ, Tolerance);
        }

        [Test]
        public void Build_UsesTheRequestedSize()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(8f, 6f, 1, 1);

            Assert.AreEqual(8f * 6f, (data.Positions[3] - data.Positions[0]) * (data.Positions[5 + 2] - data.Positions[2]), Tolerance);
        }

        [Test]
        public void Build_PointsEveryNormalUpwards()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 10f, 3, 3);

            for (int i = 0; i < data.Normals.Length; i += 3)
            {
                Assert.AreEqual(0f, data.Normals[i], Tolerance);
                Assert.AreEqual(1f, data.Normals[i + 1], Tolerance);
                Assert.AreEqual(0f, data.Normals[i + 2], Tolerance);
            }
        }

        [Test]
        public void Build_KeepsUvsInTheZeroToOneRange()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 10f, 4, 2);

            foreach (float uv in data.Uvs)
            {
                Assert.IsTrue(uv >= 0f && uv <= 1f);
            }
        }

        [Test]
        public void Build_UsesValidIndices()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 10f, 3, 3);

            foreach (int index in data.Indices)
            {
                Assert.IsTrue(index >= 0 && index < data.VertexCount);
            }
        }

        [Test]
        public void Build_WindsTheTrianglesSoTheGroundFacesUp()
        {
            PlaneMeshData data = PlaneMeshBuilder.Build(10f, 10f, 2, 2);

            for (int triangle = 0; triangle < data.TriangleCount; triangle++)
            {
                Float3 normal = PlaneMeshBuilder.TriangleNormal(data, triangle);

                // Unity renders the front side of a triangle when its vertices run clockwise
                // as seen from the camera, so a front facing ground triangle has a right
                // handed normal that points downwards (-Y) while the visible side is +Y.
                Assert.IsTrue(normal.y < 0f, "Triangle " + triangle + " is not wound for an upward facing surface.");
                Assert.AreEqual(0f, normal.x, Tolerance);
                Assert.AreEqual(0f, normal.z, Tolerance);
            }
        }

        [Test]
        public void Build_RejectsAZeroWidth()
        {
            Assert.Throws<ArgumentOutOfRangeException>(() => PlaneMeshBuilder.Build(0f, 10f, 1, 1));
        }

        [Test]
        public void Build_RejectsAZeroDepth()
        {
            Assert.Throws<ArgumentOutOfRangeException>(() => PlaneMeshBuilder.Build(10f, 0f, 1, 1));
        }

        [Test]
        public void Build_RejectsSegmentsBelowOne()
        {
            Assert.Throws<ArgumentOutOfRangeException>(() => PlaneMeshBuilder.Build(10f, 10f, 0, 1));
            Assert.Throws<ArgumentOutOfRangeException>(() => PlaneMeshBuilder.Build(10f, 10f, 1, 0));
        }
    }
}
